def transform(grid):
    g=[r[:] for r in grid]
    h,w=len(g),len(g[0])
    for c in range(w):
        if g[h-1][c] != 5: continue
        seeds=[(r,g[r][c]) for r in range(h) if g[r][c]]
        for r in range(h):
            if g[r][c]==0:
                # nearest original colored cell; ties resolve to above
                g[r][c]=min(seeds,key=lambda p:(abs(p[0]-r),p[0]>r))[1]
    return g
